const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),crypto=require('node:crypto');
const {createBundledFrontends,nativeCombo}=require('../src/bundled-frontends');
function setup(){const root=fs.mkdtempSync(path.join(os.tmpdir(),'frontend-bundle-'));const body=Buffer.from('window.packaged=true;');fs.writeFileSync(path.join(root,'code.js'),body);const entry={file:'code.js',sha256:crypto.createHash('sha256').update(body).digest('hex'),type:'text/javascript'};const manifest={version:1,index:{...entry,type:'text/html',headers:{'content-security-policy':"default-src 'self'"}},assets:{'app:/static/js/code.12345678.js':entry,'dot:/_next/static/chunks/test.js':entry},plugins:{'@deepseek-ai/test':{body:Buffer.from('window.native=true;\n').toString('base64'),map:null}}};fs.writeFileSync(path.join(root,'manifest.json'),JSON.stringify(manifest));return{root,manifest,bundle:createBundledFrontends(root)};}
test('packaged assets keep their HTTPS origin and leave private API/data untouched',()=>{const {root,bundle}=setup();try{assert.ok(bundle.resolve(new Request('https://dots.singulancelabs.com/_next/static/chunks/test.js?dpl=release')));for(const url of ['https://dots.singulancelabs.com/api/conversations/private','https://api.singulancelabs.com/auth/session','https://attacker.example/static/js/code.12345678.js'])assert.equal(bundle.resolve(new Request(url)),null);assert.equal(bundle.resolve(new Request('https://dots.singulancelabs.com/_next/static/chunks/test.js',{method:'POST'})),null);}finally{fs.rmSync(root,{recursive:true});}});
test('local workspace document retains current production CSP',()=>{const {root,bundle}=setup();try{const response=bundle.resolve(new Request('https://runtime-runner.singulancelabs.com/hivemind/app/employee/harness',{headers:{accept:'text/html'}}));assert.equal(response.headers['content-security-policy'],"default-src 'self'");}finally{fs.rmSync(root,{recursive:true});}});
test('tampered asset fails closed instead of executing',()=>{const {root,bundle}=setup();try{fs.writeFileSync(path.join(root,'code.js'),'tampered');assert.throws(()=>bundle.resolve(new Request('https://dots.singulancelabs.com/_next/static/chunks/test.js')),/integrity/);}finally{fs.rmSync(root,{recursive:true});}});
test('native combo requires the exact installed native revision',()=>{const {root,bundle,manifest}=setup();try{const combo=nativeCombo(manifest.plugins,['@deepseek-ai/test']);assert.equal(combo.rev,'d1e6d21f5c17');assert.equal(crypto.createHash('sha256').update(combo.body).digest('hex'),'ff50e696dcad1d62f6fc9da2ccf7bcaf6bf5d0d38bfd17ad4361be5edcf3870b');assert.ok(bundle.resolve(new Request(`https://runtime-runner.singulancelabs.com/plugins/??@deepseek-ai/test/client.js&rev=${combo.rev}`)));assert.equal(bundle.resolve(new Request('https://runtime-runner.singulancelabs.com/plugins/??@deepseek-ai/test/client.js&rev=000000000000')),null);assert.equal(bundle.resolve(new Request('https://runtime-runner.singulancelabs.com/plugins/??../../secrets/client.js&rev=000000000000')),null);}finally{fs.rmSync(root,{recursive:true});}});
test('network fallback preserves redirects for browser-owned OAuth navigation',async()=>{const{root}=setup();try{let handler,options;const redirect=new Response(null,{status:302,headers:{location:'https://accounts.google.com/'}});const ses={protocol:{handle:(_scheme,fn)=>{handler=fn;}},fetch:async(_request,init)=>{options=init;return redirect;}};require('../src/bundled-frontends').installBundledFrontends(ses,root);const result=await handler(new Request('https://api.singulancelabs.com/auth/login'));assert.equal(options.redirect,'manual');assert.equal(options.bypassCustomProtocolHandlers,true);assert.equal(result.status,302);assert.equal(result.headers.get('location'),'https://accounts.google.com/');}finally{fs.rmSync(root,{recursive:true});}});
